// Checkout switch branches or restore working tree files.
func (w *Worktree) Checkout(opts *CheckoutOptions) error {
	if trace.Performance.Enabled() {
		start := time.Now()
		defer func() {
			trace.Performance.Printf("performance: %.9f s: git command: git checkout", time.Since(start).Seconds())
		}()
	}

	if err := opts.Validate(); err != nil {
		return err
	}

	if opts.Create {
		if err := w.validateNewBranch(opts); err != nil {
			return err
		}
	}

	c, err := w.getCommitFromCheckoutOptions(opts)
	if err != nil {
		return err
	}

	ro := &ResetOptions{
		Commit:     c,
		Mode:       MergeReset,
		SparseDirs: opts.SparseCheckoutDirectories,
	}
	if opts.Force {
		ro.Mode = HardReset
	} else if opts.Keep {
		ro.Mode = SoftReset
	}

	if err := w.reset(ro); err != nil {
		return err
	}

	// A failed tree read must not switch HEAD or create a branch. Resetting
	// through the current HEAD would also move the branch we are leaving.
	if opts.Create {
		if err := w.r.Storer.SetReference(plumbing.NewHashReference(opts.Branch, c)); err != nil {
			return err
		}
	}
	if !opts.Hash.IsZero() && !opts.Create {
		return w.setHEADToCommit(c)
	}
	return w.setHEADToBranch(opts.Branch, c)
}

func (w *Worktree) validateNewBranch(opts *CheckoutOptions) error {
	// Git applies its branch-name rules to the shorthand a user types, so
	// recover the shorthand before checking a name that is one. A name that is
	// not under refs/heads/ gets the reference-name rules alone: handing it to
	// ValidateBranchName would splice a second "refs/heads/" in front and
	// judge that instead, which accepts the one-level spellings Validate
	// exists to refuse. That arm is not a second gate — "HEAD" reaches it and
	// passes, because Validate carves HEAD out; what stops it is the existing-
	// reference check below.
	if name, ok := strings.CutPrefix(opts.Branch.String(), plumbing.RefHeadPrefix); ok {
		if err := plumbing.ValidateBranchName(name); err != nil {
			return err
		}
	} else if err := opts.Branch.Validate(); err != nil {
		return err
	}

	_, err := w.r.Storer.Reference(opts.Branch)
	if err == nil {
		return fmt.Errorf("a branch named %q already exists", opts.Branch)
	}

	if !errors.Is(err, plumbing.ErrReferenceNotFound) {
		return err
	}

	if opts.Hash.IsZero() {
		ref, err := w.r.Head()
		if err != nil {
			return err
		}

		opts.Hash = ref.Hash()
	}

	return nil
}

func (w *Worktree) getCommitFromCheckoutOptions(opts *CheckoutOptions) (plumbing.Hash, error) {
	hash := opts.Hash
	if hash.IsZero() {
		b, err := w.r.Reference(opts.Branch, true)
		if err != nil {
			return plumbing.ZeroHash, err
		}

		hash = b.Hash()
	}

	o, err := w.r.Object(plumbing.AnyObject, hash)
	if err != nil {
		return plumbing.ZeroHash, err
	}

	switch o := o.(type) {
	case *object.Tag:
		if o.TargetType != plumbing.CommitObject {
			return plumbing.ZeroHash, fmt.Errorf("%w: tag target %q", object.ErrUnsupportedObject, o.TargetType)
		}

		return o.Target, nil
	case *object.Commit:
		return o.Hash, nil
	}

	return plumbing.ZeroHash, fmt.Errorf("%w: %q", object.ErrUnsupportedObject, o.Type())
}

func (w *Worktree) setHEADToCommit(commit plumbing.Hash) error {
	head := plumbing.NewHashReference(plumbing.HEAD, commit)
	return w.r.Storer.SetReference(head)
}

func (w *Worktree) setHEADToBranch(branch plumbing.ReferenceName, commit plumbing.Hash) error {
	target, err := w.r.Storer.Reference(branch)
	if err != nil {
		return err
	}

	var head *plumbing.Reference
	if target.Name().IsBranch() {
		head = plumbing.NewSymbolicReference(plumbing.HEAD, target.Name())
	} else {
		head = plumbing.NewHashReference(plumbing.HEAD, commit)
	}

	return w.r.Storer.SetReference(head)
}

