// transport operations.
func (w *Worktree) PullContext(ctx context.Context, o *PullOptions) error {
	if trace.Performance.Enabled() {
		start := time.Now()
		defer func() {
			trace.Performance.Printf("performance: %.9f s: git command: git pull", time.Since(start).Seconds())
		}()
	}

	if err := o.Validate(); err != nil {
		return err
	}

	remote, err := w.r.Remote(o.RemoteName)
	if err != nil {
		return err
	}

	fetchHead, err := remote.fetch(ctx, &FetchOptions{
		RemoteName:    o.RemoteName,
		RemoteURL:     o.RemoteURL,
		Depth:         o.Depth,
		ClientOptions: o.ClientOptions,
		Progress:      o.Progress,
		Force:         o.Force,
	})

	updated := true
	if errors.Is(err, NoErrAlreadyUpToDate) {
		updated = false
	} else if err != nil {
		return err
	}

	ref, err := storer.ResolveReference(fetchHead, o.ReferenceName)
	if err != nil {
		return err
	}

	head, err := w.r.Head()
	if err == nil {
		// if we don't have a shallows list, just ignore it
		shallowList, _ := w.r.Storer.Shallow()

		headAheadOfRef, err := isFastForward(w.r.Storer, ref.Hash(), head.Hash(), shallowList)
		if err != nil {
			return err
		}

		if !updated && headAheadOfRef {
			return NoErrAlreadyUpToDate
		}

		ff, err := isFastForward(w.r.Storer, head.Hash(), ref.Hash(), shallowList)
		if err != nil {
			return err
		}

		if !ff {
			return ErrNonFastForwardUpdate
		}
	}

	if err != nil && !errors.Is(err, plumbing.ErrReferenceNotFound) {
		return err
	}

	if err := w.reset(&ResetOptions{
		Mode:   MergeReset,
		Commit: ref.Hash(),
	}); err != nil {
		return err
	}

	// Publish the fetched commit only after the reset succeeds. updateHEAD
	// also creates the current branch when pulling into an unborn HEAD.
	if err := w.updateHEAD(ref.Hash()); err != nil {
		return err
	}

	if o.RecurseSubmodules != NoRecurseSubmodules {
		return w.updateSubmodules(ctx, &SubmoduleUpdateOptions{
			RecurseSubmodules: o.RecurseSubmodules,
			ClientOptions:     o.ClientOptions,
		})
	}

	return nil
}

