			fs := &failingCreateFS{Filesystem: memfs.New(), name: "a"}
			s := memory.NewStorage()
			r, err := Init(s, WithWorkTree(fs))
			require.NoError(t, err)
			w, err := r.Worktree()
			require.NoError(t, err)
			sig := &object.Signature{Name: "t", Email: "t@t", When: time.Unix(1, 0)}

