func TestProbeCDiffUnsafeSubtree(t *testing.T) {
	for _, dir := range []string{".git", "..", "a/b"} {
		s := memory.NewStorage()
		b := s.NewEncodedObject()
		b.SetType(plumbing.BlobObject)
		w, _ := b.Writer()
		w.Write([]byte("x"))
