		bh, _ := s.SetEncodedObject(b)
		sub := probeStore(t, s, &Tree{Entries: []TreeEntry{{Name: "config", Mode: filemode.Regular, Hash: bh}}})
		empty := probeStore(t, s, &Tree{})
		to := probeStore(t, s, &Tree{Entries: []TreeEntry{{Name: dir, Mode: filemode.Dir, Hash: sub.Hash}}})
