		empty := probeStore(t, s, &Tree{})
		to := probeStore(t, s, &Tree{Entries: []TreeEntry{{Name: dir, Mode: filemode.Dir, Hash: sub.Hash}}})
		ch, err := DiffTree(empty, to)
		if err != nil {
			t.Logf("%s: DiffTree err=%v", dir, err)
			continue
		}
		for _, c := range ch {
			f1, f2, ferr := c.Files()
			t.Logf("%s: change name=%q files=%v,%v err=%v", dir, c.To.Name, f1, f2 != nil, ferr)
		}
	}
}
EOF
